String rootOf(String w) {
    Node cur = root;
    StringBuilder sb = new StringBuilder();
    for (char c : w.toCharArray()) {
        cur = cur.next[c - 'a'];
        if (cur == null) return w;         // no root exists
        sb.append(c);
        if (cur.word) return sb.toString();  // the SHORTEST root wins
    }
    return w;
