void insert(int x) {
    Node cur = root;
    for (int b = 31; b >= 0; b--) {
        int bit = (x >> b) & 1;
        if (cur.child[bit] == null) cur.child[bit] = new Node();
        cur = cur.child[bit];
    }
}

int best(int x) {
    Node cur = root; int res = 0;
    for (int b = 31; b >= 0; b--) {
        int want = 1 - ((x >> b) & 1);              // prefer the opposite bit
        if (cur.child[want] != null) { res |= (1 << b); cur = cur.child[want]; }
        else cur = cur.child[1 - want];
    }
    return res;
}
